(()=>{if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));const button=document.getElementById('installApp');if(!button)return;let promptEvent=null;const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(standalone)return;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();promptEvent=event;button.hidden=false});button.addEventListener('click',async()=>{if(promptEvent){promptEvent.prompt();await promptEvent.userChoice;promptEvent=null;button.hidden=true;return}const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);alert(ios?'اضغط زر المشاركة ثم اختر «إضافة إلى الشاشة الرئيسية».':'افتح قائمة المتصفح واختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».')});if(/iphone|ipad|ipod/i.test(navigator.userAgent))button.hidden=false})();
